from dog_lib import *
# ---------------- inside the eye ----------------
E1 = [R('36.5', '36-5-vision')]
def EYE(id, title, scale, summary, basics, deeper, expert, facts, human, cert='C2', ext=None, openq=None, parts=None):
    N(id, title, 'structure', scale, ['dog_eye'], summary, basics, deeper, expert, facts, cert=cert, refs=E1, ext=ext or [DVMEYE], human=human, openq=openq, parts=parts)
EYE('dog_sclera', 'Sclera (white of the eye)', .002, 'The tough white wall of the eyeball.', 'The sclera is the outer coat of the eye. A dog\'s sclera shows much less white than a person\'s because the iris fills most of the opening.', 'It is connective tissue that holds the shape of the eye and anchors the muscles that turn it.', 'The model draws it as a shell.', [['Role', 'protective outer wall']], [('eye_l', 'In people: the same layer; more of it is visible, so the "whites" of the eyes show.')])
EYE('dog_choroid', 'Choroid (dark layer)', .0005, 'A dark, blood-rich layer behind the retina that feeds it and absorbs stray light.', 'Under the sensing layer there is a layer full of blood vessels and dark pigment. It nourishes the retina. In the part of the dog\'s eye below the tapetum, it is dark.', 'In the upper part of a dog\'s eye the tapetum lies in the choroid; in the lower part the choroid is dark and absorbs light.', 'The model shows the dark part only in the lower half.', [['Role', 'blood supply and light absorption']], [('retina', 'In people: the choroid is dark all the way round; there is no tapetum.')])
EYE('dog_tapetum', 'Tapetum lucidum', .0004, 'A shiny layer behind the retina that bounces light back through it for a second chance, so dogs see better in dim light and their eyes glow in a torch beam.',
  'This is something you do not have. Light that passes through the retina without being caught hits the tapetum and is reflected back through the retina. That is why dog eyes glow green or yellow in car headlights. The cost is that the image is slightly blurred.',
  'The tapetum of a dog lies in the upper half of the back of the eye, between the choroid and the retinal pigment layer. It is made of 9-20 layers of flat, rectangular cells holding zinc-rich rods lined up in parallel, which reflect light by interference. It looks yellow-green in adult dogs and blue in puppies until about four months old. Cats\' tapeta use riboflavin and zinc; the dog\'s uses zinc.',
  'The reflecting structure thins toward the edge of the eye. Some drugs and a hereditary zinc deficiency in some beagles can damage the tapetal cells. A dog\'s tapetum reflects a fraction of the light that is not stated here (the figure for cats should not be assumed to apply). The tapetum scene is reached with the button on the retina or tapetum card.',
  [['Position', 'upper half of the fundus'], ['Layers', '9-20 cell layers'], ['Cell contents', 'zinc-rich rodlets'], ['Colour', 'yellow-green (adult), blue (puppy)']], [('retina', 'In people: absent. The human retina has no reflecting layer behind it, so human eyes do not shine in the dark.')], ext=[WTAP, WCOMP], openq=['How much light does a dog\'s tapetum return, and how much sharpness does it cost? Published values were not found.'])
EYE('dog_retina', 'Retina', .0002, 'The retina is the sheet of light-sensing cells at the back of the eye: many rods for dim light, fewer cones for colour.',
  'The retina turns light into nerve signals. A dog has far more rod cells than cones, so it sees well in dim light, and only two kinds of cone, so its colour world is limited (roughly blue and yellow, with less red-green). Press the button to look at its cells.',
  'Dog cones peak at about 429 nm (blue) and about 555 nm (green-yellow), so dogs are dichromats, like a person with red-green colour blindness. In the area centralis (the sharpest spot) there are about 23 rods for each cone; in the lower periphery about 41.',
  'In a study of the beagle retina cones numbered about 23,000-26,000 per square millimetre at the area centralis and rods about 501,000 per square millimetre. The cone peak sensitivities 429 and 555 nm are from the same study; another source gives 440 and 555 nm.',
  [['Cone types', '2 (≈ 429 and ≈ 555 nm)'], ['Rod : cone ratio', '≈ 23 : 1 (area centralis), ≈ 41 : 1 (lower periphery)'], ['Visual acuity', '≈ 20/75 (estimate)']], [('retina', 'In people: three cone types (blue, green, red) and a fovea; no tapetum.'), ('rod_cell', 'Compare the human rod cell.'), ('cone_cell', 'Compare the human cone cell.')], ext=[BEAGLE, DVMEYE], parts=['dog_rod', 'dog_cone'])
bars('dog_retina', [('dog: rods per cone (area centralis)', 22.8), ('dog: rods per cone (lower periphery)', 41.4), ('dog: cone types', 2), ('human: cone types', 3)], 'ratio or count', 'Beagle retina (Mol Vis 2008): about 23 rods for each cone at the sharpest spot and about 41 at the lower edge. Cone types: dog 2, human 3.')
EYE('dog_lens', 'Lens', .008, 'The lens is a clear disc that fine-tunes the focus of light on the retina.', 'The cornea does most of the bending of light; the lens changes shape to adjust the focus for near and far.', 'The same structure as the human lens. In dogs it is round and fairly large, and it stiffens with age.', 'The model draws a smooth oval.', [['Role', 'adjustable focus']], [('lens', 'In people: the same part.')])
EYE('dog_cornea', 'Cornea', .0005, 'The clear front window of the eye.', 'It lets light in and does most of the focusing. It is kept wet by tears.', 'The same as in people.', 'The model draws the cornea as a clear cap.', [['Role', 'window and main focusing surface']], [('cornea', 'In people: the same part.')])
EYE('dog_iris', 'Iris and pupil', .01, 'The coloured ring that opens and closes the pupil to let in more or less light.', 'The pupil of a dog is round and is a hole, not a coloured part; muscles in the iris change its size.', 'Same as in people: round pupil in dogs.', 'The model draws the iris and pupil as a ring.', [['Pupil', 'round']], [('iris', 'In people: the same part.')])
EYE('dog_vitreous', 'Vitreous body', .01, 'A clear jelly fills the middle of the eyeball and holds the retina in place.', 'The jelly is mostly water. It keeps the eye round.', 'Same as in people.', 'The model draws it as a transparent ball.', [['Role', 'shape and support']], [('vitreous_humor', 'In people: the same.')])
# nose and ear
N('dog_turb_olf', 'Ethmoturbinates (smell lining)', 'structure', .04, ['dog_nose'], 'At the back of a dog\'s nose, thin scrolls of bone folded up like parchment are covered with a smell-sensing lining that is far larger than yours.',
  'Air breathed in flows through the nose; some of it goes to the back where the smell-sensing scrolls are. The folding packs a large surface into a small space. Press the button to look inside the lining.',
  'In a dog the lining area is about 170 cm² (one reference) compared with about 5-10 cm² in a person, and the lining holds hundreds of millions of receptor cells (a secondary source gives about 125-300 million for dogs and about 5 million for people). A dog has about 800 working smell receptor genes, people about 400. The folding itself is more intricate in the real nose than the schematic scrolls drawn here.',
  'Dogs sniff in short bursts, and the nasal passage divides air into a route for smell and a route to the lungs. Detection thresholds are often quoted as thousands of times lower than ours, but the numbers depend on the odour and the method, and no solid source was found for them here.',
  [['Lining area', '≈ 170 cm² (dog) vs ≈ 10 cm² (human)'], ['Receptor cells', '≈ 125-300 million (dog, secondary source) vs ≈ 5 million (human)'], ['Receptor genes', '≈ 800 (dog) vs ≈ 400 (human)']], cert='C2', refs=[R('36.3', '36-3-taste-and-smell')], ext=[WOLF, WOR, QUIG, OSM363, src('The sense of smell: dogs or us (RAPS)', 'https://www.raps.org/resource/the-sense-of-smell-dogs-or-us.html')],
  human=[('nose_airway', 'In people: the lining is on the roof of the nose, a patch of about 5 cm² (OpenStax) and the scrolls (turbinates) are small.')], parts=['dog_olfactory_epithelium'], dyk='A dog\'s nose also has a second chemical organ, the vomeronasal organ, above the roof of the mouth, for chemical signals from other animals.',
  openq=['How many receptor cells does a dog have? The figures in circulation are old estimates from secondary sources.'])
bars('dog_turb_olf', [('dog: epithelium area (cm²)', 170), ('human: epithelium area (cm²)', 10), ('dog: functional receptor genes (≈)', 800), ('human: functional receptor genes (≈)', 400)], 'area in cm² or number of genes', 'Approximate comparison: lining area from the Olfaction reference (dog about 170 cm², human about 10 cm²) and receptor gene counts from the receptor-gene comparison of Quignon et al. 2003 and Wikipedia (about 800 and about 400).', logy=True)
N('dog_turb_resp', 'Maxilloturbinates (airway lining)', 'structure', .04, ['dog_nose'], 'The scrolls at the front of the nose warm, wet and clean the air on its way in.',
  'These scrolls are lined with moist, blood-rich skin. They warm cold air and add moisture, and trap dust and germs on mucus.', 'In panting they also give off heat: moisture evaporates from them and cools the blood. This airway lining lies in front of the smell lining and is not itself the sense of smell.', 'The shape drawn is a schematic of a much finer structure.', [['Role', 'warming, humidifying, cooling']], cert='C2', refs=[A('22.1', '22-1-organs-and-structures-of-the-respiratory-system')], ext=[MERCK_T], human=[('nose_airway', 'In people: the same job done by the nasal conchae.')])
N('dog_ear_canal', 'Ear canal', 'structure', .08, ['dog_ear'], 'A dog\'s ear canal is L-shaped: down first, then inward to the eardrum.', 'Sound goes down the vertical part of the canal and then turns inward. The bend traps dirt and moisture, which is why dogs with floppy ears are prone to infections.', 'The canal is lined with skin and wax glands. It has the bend described above.', 'The model draws a simple bent tube.', [['Shape', 'vertical then horizontal']], cert='C2', refs=[R('36.4', '36-4-hearing-and-vestibular-sensation')], ext=[WDA], human=[('human_body', 'In people the canal is shorter and almost straight.')])
N('dog_eardrum', 'Eardrum', 'structure', .01, ['dog_ear'], 'A thin membrane at the inner end of the ear canal that vibrates with sound.', 'Sound waves in the canal make the eardrum vibrate. The vibration is passed on to the three tiny bones of the middle ear.', 'The same as in people.', 'The model draws it as a disc.', [['Role', 'turns air pressure waves into vibration']], cert='C1', refs=[R('36.4', '36-4-hearing-and-vestibular-sensation')], human=[('human_body', 'In people: the same part.')])
N('dog_bulla', 'Middle ear (bulla)', 'structure', .02, ['dog_ear'], 'The middle ear sits in a bony bubble, the bulla, on the underside of the skull.', 'Three tiny bones carry the vibration from the eardrum to the inner ear. In a dog the cavity is a bulge you can see on the skull from below.', 'Same three bones as in people (the hammer, anvil and stirrup).', 'The model draws the bubble without the three bones.', [['Bones inside', '3 (malleus, incus, stapes)']], cert='C2', refs=[R('36.4', '36-4-hearing-and-vestibular-sensation')], human=[('human_body', 'In people: the same chain of three bones; there is no bulla bulge.')])
N('dog_cochlea', 'Cochlea and balance canals', 'structure', .01, ['dog_ear'], 'The cochlea is a snail-shaped tube in the skull that turns vibration into nerve signals; next to it, three loops sense turning of the head.',
  'The cochlea holds the hair cells that detect sound. Its different parts react to different pitch. The loops next to it, the semicircular canals, are the balance organ.', 'A dog hears from about 67 Hz to about 45 kHz, a wider range than a person (about 20 Hz to 20 kHz).', 'The model draws the snail and the loops at a schematic size.', [['Hearing range', '≈ 67 Hz to 45 kHz']], cert='C2', refs=[R('36.4', '36-4-hearing-and-vestibular-sensation')], ext=[WHEAR], human=[('human_body', 'In people: the same inner ear; the range of hearing is narrower.')])
